    // -- NOEFF: statement with no effect ------------------------------------

    #[test]
    fn noeff_fires_on_discarded_expression() {
        let diags = lint_file(&*engine(), "function foo()\n    1 + 2;\nend\n");
        assert!(has_id(&diags, "NOEFF"), "got: {diags:?}");
    }

    #[test]
    fn noeff_ok_on_assignment() {
