        );
        assert!(!has_id(&diags, "DEFNU"), "got: {diags:?}");
    }

    // -- UNRCH: unreachable code --------------------------------------------

    #[test]
    fn unrch_fires_after_return() {
        let diags = lint_file(&*engine(), "function foo()\n    return;\n    x = 1;\nend\n");
        assert!(has_id(&diags, "UNRCH"), "got: {diags:?}");
