    }

    // -- VUNUS: assigned in branches but unused after -----------------------

    #[test]
    fn vunus_fires_on_branch_assignment_unused() {
        let diags = lint_file(
            &*engine(),
            "function foo(flag)\n    if flag\n        x = 1;\n    else\n        x = 2;\n    end\nend\n",
        );
