        );
        assert!(!has_id(&diags, "VUNUS"), "got: {diags:?}");
    }

    // -- MANU: method defined but never called ------------------------------

    #[test]
    fn manu_fires_on_uncalled_method() {
        let diags = lint_file(
            &*engine(),
            "classdef Foo\n    methods\n        function y = bar()\n            y = 1;\n        end\n    end\nend\n",
        );
