            &*engine(),
            "function foo()\n    s.a = 1;\n    s.b = 2;\n    x = s.a + s.b;\n    disp(x);\nend\n",
        );
        assert!(!has_id(&diags, "MSNE"), "got: {diags:?}");
    }
